example.content:
eda.sys_Dialog.showSelectDialog(
  [
    { value: 'TOP', displayContent: '顶层' },
    { value: 'BOTTOM', displayContent: '底层' }
  ],
  '请选择丝印放置的层',   // 选择框上方文字
  '设置会应用到全部丝印', // 选择框下方文字
  '丝印层设置',           // 窗口标题
  'TOP',                  // 默认选项（匹配选项的 value）
  false,                  // 单选
  (value) => {
    console.log('单选结果：', value);
  }
);

eda.sys_Dialog.showSelectDialog(
  ['DRC', 'BOM', 'Gerber'],
  '请选择需要导出的内容', // 多选框上方文字
  '',                    // 多选框下方文字
  '导出设置',            // 窗口标题
  ['DRC', 'BOM'],        // 默认选项数组
  true,                  // 多选
  (values) => {
    console.log('多选结果：', values);
  }
);
